'use strict';
/*
 * Builds stage1core.js — the browser bundle of the Stage 1
 * core modules (identity, ledger, capture, migration) for the
 * background service worker. Each module is wrapped in an
 * IIFE; the two Node require lines are resolved against the
 * globals the modules themselves publish. Deterministic:
 * same sources, same bundle. Run: node build-stage1-bundle.js
 */
const fs = require('node:fs');
const path = require('node:path');

const dir = __dirname;

function loadModule(file, replacements) {
  let src = fs.readFileSync(path.join(dir, file), 'utf8');
  for (const [from, to] of replacements) {
    if (!src.includes(from)) {
      throw new Error('bundle: expected line not found in ' + file + ': ' + from);
    }
    src = src.replace(from, to);
  }
  return '(function () {\n' + src + '\n})();\n';
}

const REQUIRE_IDENTITY = "const PBIdentity = require('./identity.js');";
const FROM_GLOBAL = 'const PBIdentity = globalThis.PBIdentity;';

const parts = [
  '/* Pulse Bridge — stage1core.js (GENERATED by build-stage1-bundle.js; do not edit by hand)',
  ' * The Stage 1 core: PBIdentity, PBLedger, PBCapture, PBMigration,',
  ' * published on globalThis for the background service worker. */',
  '',
  loadModule('identity.js', []),
  loadModule('ledger.js', [[REQUIRE_IDENTITY, FROM_GLOBAL]]),
  loadModule('capture.js', [[REQUIRE_IDENTITY, FROM_GLOBAL]]),
  loadModule('migration.js', []),
];

fs.writeFileSync(path.join(dir, 'stage1core.js'), parts.join('\n'));
console.log('stage1core.js written');
